export type ReqType =
  | "GET"
  | "POST"
  | "PUT"
  | "PATCH"
  | "DELETE"
  | "OPTIONS"
  | "HEAD"
  | "get"
  | "post"
  | "put"
  | "patch"
  | "delete"
  | "options"
  | "head"
  | "Get"
  | "Post"
  | "Put"
  | "Patch"
  | "Delete"
  | "Options"
  | "Head";

export interface ServerFunctionConfig {
  /**
   * Enable or disable server function logging.
   * @default true
   */
  enabled?: boolean;
  /**
   * Terminal output format: "tree" (nested under request line like Next.js) or "inline" ([server-fn] badge).
   * @default "tree"
   */
  format?: "tree" | "inline";
  /**
   * Log arguments passed to the server function.
   * @default true
   */
  logArgs?: boolean;
  /**
   * Log returned value or error from the server function.
   * @default true
   */
  logReturns?: boolean;
  /**
   * Maximum argument/return value object nesting depth.
   * @default 2
   */
  maxDepth?: number;
  /**
   * Maximum array elements or object keys to log before truncating.
   * @default 3
   */
  maxBreadth?: number;
  /**
   * Maximum string length before truncating with ellipsis.
   * @default 40
   */
  maxStringLength?: number;
  /**
   * Inject interactive in-browser Server Function DevTools overlay/pill.
   * @default true
   */
  ui?: boolean;
  /**
   * Mirror server function logs to the browser developer console.
   * @default false
   */
  browserConsole?: boolean;
  /**
   * Custom resolver to identify server functions from request headers or URLs.
   */
  resolveServerFn?: (req: IncomingMessage) => ServerFnDetails | undefined;
}

export interface BrowserLoggerConfig {
  /**
   * Enable the in-browser floating DevTools overlay and drawer for inspecting server functions.
   * @default true
   */
  serverFunctionUi?: boolean;
  /**
   * Emit one compact NDJSON row per browser log event instead of pretty lines.
   * @default false
   */
  json?: boolean;

  /**
   * Colour override: set `false` to force plain (ANSI-free) terminal output
   * even on a real TTY. Defaults to automatic TTY / `NO_COLOR` / `FORCE_COLOR`
   * handling.
   */
  stripColors?: boolean;
}

export interface RequestLoggerConfig {
  excludeReqType?: ReqType[];
  excludeUrls?: string[];
  /**
   * Filter out Vite module compilation noise: both dependency modules
   * (`/node_modules/`, `/@vite`, `/@id/`) and your own source modules
   * (`/src/**`, `*.ts|tsx|js|jsx|css`). Set to `false` to log every module
   * request. Defaults to `true`.
   */
  excludeModules?: boolean;
  /**
   * Filter out `/api` endpoint requests from terminal logs.
   * Matches the `/api` path segment only, so `/api-key` is still logged.
   * @default false
   */
  excludeApis?: boolean;
  /**
   * Collapse repeated requests to the same URL within `repeatWindowMs` into a
   * single trailing `(xN)` line instead of printing one line each.
   * @default true
   */
  groupRepeats?: boolean;
  /**
   * Window used to group repeated requests.
   * @default 1000
   */
  repeatWindowMs?: number;
  /**
   * Print a diagnostic when many modules are requested a second time without an
   * intervening document request, which means the entry graph ran twice in one
   * page load.
   * @default true
   */
  detectGraphReevaluation?: boolean;
  resolveRoute?: (url: string) => string | undefined | null;
  /**
   * Configuration for Server Function / Server Action execution logging.
   * Set to `false` to disable server function execution logging.
   * @default true
   */
  serverFunctions?: boolean | ServerFunctionConfig;
  /**
   * Respect the terminal's color capabilities: colors are stripped automatically
   * when output is piped or `NO_COLOR` is set, and kept with `FORCE_COLOR`.
   * @default true
   */
  stripColors?: boolean;
  /**
   * Emit one compact NDJSON row per log event instead of pretty colored lines.
   * Pairs well with `pnpm dev 2>&1 | jq`.
   * @default false
   */
  json?: boolean;
  /**
   * Rolling latency footer: prints `p50/p95/p99` request latency and volume once
   * per window while traffic is flowing (no output while the server is idle).
   * @default true
   */
  summaryStats?: boolean | { windowMs?: number; minSamples?: number };
}

/**
 * Default request URL exclusions shared by every adapter. Root-anchored, so
 * plugin code (e.g. `/src/foo.ts`) is never caught. TanStack layers its own
 * extra patterns on top via `TANSTACK_EXCLUDE_PATTERNS`.
 */
export const DEFAULT_EXCLUDE_URLS = [
  "?import",
  "vite_ping",
  "@fs",
  "/@vite",
  "/@id/",
  "/@react-refresh",
  "/node_modules/",
  "/.well-known",
  "/__hyperlog",
];

/** Maximum accepted body size for the SPA route reporting endpoint. */
const MAX_ROUTE_BODY_BYTES = 64 * 1024;

let nextExclusionConfigId = 1;

/**
 * Allocates a unique plugin-instance id for the native exclusion cache.
 *
 * Each `requestLogger` instance registers its own exclusion config under this
 * id, so several plugins can coexist in one process without clobbering each
 * other's configuration.
 */
export function allocateExclusionConfigId(): number {
  return nextExclusionConfigId++;
}

/**
 * Collects a request body as bytes.
 *
 * Concatenating chunks with `body += chunk` decodes each Buffer independently, so
 * a multi-byte character split across a chunk boundary is silently corrupted.
 * Buffering the raw bytes and decoding once at the end avoids that.
 */
function readBody(req: any, res: any, limit: number): Promise<Buffer | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let settled = false;

    const done = (value: Buffer | null) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };

    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > limit) {
        if (!res.headersSent) {
          res.statusCode = 413;
          res.end();
        }
        req.destroy();
        done(null);
        return;
      }
      chunks.push(chunk);
    });

    req.on("end", () => done(Buffer.concat(chunks)));
    req.on("error", () => done(null));
    req.on("aborted", () => done(null));
  });
}

export interface RoutePayload {
  routeId?: string;
  path?: string;
  params?: string | null;
  durationMs?: number | null;
  isPreload?: boolean | null;
}

/**
 * Same-origin guard for the SPA route reporting endpoint.
 *
 * A browser `fetch`/XHR always sends an `Origin` header, so cross-site pages (or
 * a DNS-rebinding attacker hitting the dev server directly) can be identified
 * by shipping their requests with an `Origin` that does not match the `Host`
 * the dev server received the request on. Those are *remote* forgeries and are
 * rejected; same-page clients match, and header-less non-browser clients
 * (curl, IDE tools) are unaffected.
 */
function isSameOriginDevRequest(origin: string | undefined, host: string | undefined): boolean {
  if (!origin || !host) return false;
  let originHost: string;
  try {
    originHost = new URL(origin).host;
  } catch {
    return false;
  }
  return originHost.toLowerCase() === host.toLowerCase();
}

/** Sink-backed route reporter shared by the HTTP endpoint and WS handlers. */
export function routeEventSinkHandler(sink: LogSink): (data: RoutePayload) => void {
  return (data) => {
    const logString = formatRouteLog(
      data.routeId || data.path || "",
      data.path || "",
      data.params ?? null,
      data.durationMs ? Number(data.durationMs) : null,
      Boolean(data.isPreload),
    );
    sink.print(logString, {
      kind: "route",
      ts: Date.now(),
      routeId: data.routeId ?? null,
      path: data.path ?? null,
      params: data.params ?? null,
      durationMs: data.durationMs ? Number(data.durationMs) : null,
      isPreload: Boolean(data.isPreload),
    });
  };
}

/**
 * Lazily-created module sink for standalone callers (direct `attachRouteEndpoint`
 * use, custom integrations) so even those prints follow the same color policy,
 * batching, and NDJSON shape as the plugin-managed output.
 */
let fallbackSink: LogSink | null = null;
function moduleSink(): LogSink {
  if (!fallbackSink) fallbackSink = createLogSink();
  return fallbackSink;
}

/** Logs one client-reported SPA route transition. */
export function logRouteEvent(data: RoutePayload): void {
  routeEventSinkHandler(moduleSink())(data);
}

/**
 * Attaches the SPA route reporting endpoint exactly once per dev server.
 *
 * `requestLogger`, `browserLogger`, and the TanStack adapter all want this route,
 * and registering it from more than one place produced copies that had already
 * started to drift (including the chunked-UTF-8 body bug). The WeakSet keeps the
 * first registration regardless of plugin order.
 */
const routeEndpointServers = new WeakSet<object>();

export function attachRouteEndpoint(server: any, onRoute: (data: RoutePayload) => void = logRouteEvent): void {
  if (routeEndpointServers.has(server)) return;
  routeEndpointServers.add(server);

  server.middlewares.use((req: any, res: any, next: () => void) => {
    if (req.url !== "/__hyperlog/route" || req.method !== "POST") {
      return next();
    }

    // Reject cross-origin route forgeries before reading the body (see the
    // doc comment on `isSameOriginDevRequest`). Requests without an Origin
    // header are non-browser clients (curl, IDE tools) and pass through.
    const originHeader = req.headers?.origin;
    if (originHeader && !isSameOriginDevRequest(originHeader, req.headers?.host)) {
      res.statusCode = 403;
      res.end();
      return;
    }

    void readBody(req, res, MAX_ROUTE_BODY_BYTES).then((body) => {
      if (body) {
        try {
          onRoute(JSON.parse(body.toString("utf8")));
        } catch {
          // Malformed payloads are ignored rather than crashing the dev server.
        }
      }
      if (!res.writableEnded && !res.headersSent) {
        res.statusCode = body ? 204 : 400;
        res.end();
      }
    });
  });
}

export function requestLogger(config?: RequestLoggerConfig): Plugin {
  const excludeModules = config?.excludeModules ?? true;
  const groupRepeats = config?.groupRepeats ?? true;
  const repeatWindowMs = config?.repeatWindowMs ?? 1000;
  const detectGraphReevaluation = config?.detectGraphReevaluation ?? true;

  const sf = config?.serverFunctions;
  // SAFETY: sf is validated to be a configuration object and not a boolean
  const serverFnConfig = Boolean(sf) && sf !== true ? (sf as ServerFunctionConfig) : null;
  const isServerFnLoggingEnabled = serverFnConfig !== null && serverFnConfig.enabled !== false;
  const serverFnFormat = serverFnConfig?.format ?? "tree";

  const exclusions = [
    ...DEFAULT_EXCLUDE_URLS,
    ...(config?.excludeUrls || []),
    ...(config?.excludeApis ? ["/api"] : []),
  ];
  const excludedMethods = config?.excludeReqType
    ? new Set(config.excludeReqType.map((type) => type.toUpperCase()))
    : null;
  const resolveRoute = config?.resolveRoute;

  const jsonMode = config?.json === true;
  const summaryConfig = config?.summaryStats;
  const summaryEnabled = summaryConfig !== false;
  // SAFETY: with `true` and `false` excluded, a defined value is necessarily the object form.
  const summaryOptions: SummaryOptions =
    summaryEnabled && summaryConfig !== true ? ((summaryConfig ?? {}) as SummaryOptions) : {};
  const summaryWindowMs = Math.max(200, summaryOptions.windowMs ?? 10_000);

  // Registered once so the per-request hot path evaluates exclusions natively
  // via the shared `observeRequest` crossing instead of marshalling this array
  // across the NAPI boundary on every request.
  const exclusionConfigId = allocateExclusionConfigId();
  registerExclusionConfig(exclusionConfigId, exclusions, excludeModules);

  return {
    name: "vite-plugin-request-logging-rust",
    apply: "serve",
    configureServer(server) {
      interface PendingRepeat {
        timer: ReturnType<typeof setTimeout>;
        count: number;
        totalDurationMs: number;
        status: number;
        method: string;
        url: string;
      }

      const repeats = new Map<string, PendingRepeat>();

      // Shared output pipeline: color policy (TTY/NO_COLOR), microtask-batched
      // stdout, NDJSON mode, and the rolling latency summary all hang off this.
      const sink = createLogSink({ json: jsonMode, stripColors: config?.stripColors });
      const summary = summaryEnabled ? createSummaryTracker(summaryOptions) : null;
      let summaryFlushQueued = false;

      const flushRepeat = (key: string, entry: PendingRepeat) => {
        repeats.delete(key);
        if (entry.count <= 1) return;
        const repeatLine = formatLogEntry(
          entry.url,
          entry.method,
          entry.status,
          entry.totalDurationMs,
          null,
          null,
          null,
          entry.count,
        );
        sink.print(
          repeatLine,
          buildRequestEvent(entry.url, entry.method, entry.status, entry.totalDurationMs, { repeat: entry.count }),
        );
      };

      server.httpServer?.on("close", () => {
        for (const [key, entry] of repeats) {
          clearTimeout(entry.timer);
          flushRepeat(key, entry);
        }
        sink.flush();
      });

      // --- Graph re-evaluation detection -------------------------------------
      // Observed before exclusions so it still sees module traffic that is not
      // logged, and reset by each document request to scope it to one page load.
      const detector = new GraphReevaluationDetector();

      const observe = (isModule: boolean, url: string) => {
        const report = detector.observe(isModule, url);
        if (report) {
          sink.print(formatGraphReevaluation(report.distinctModules, report.repeatedRequests, report.windowMs), {
            kind: "graph",
            ts: Date.now(),
            distinctModules: report.distinctModules,
            repeatedRequests: report.repeatedRequests,
            windowMs: report.windowMs,
          });
        }
      };

      const handleRoute = routeEventSinkHandler(sink);

      attachRouteEndpoint(server, handleRoute);

      server.middlewares.use((req, res, next) => {
        const url = req.originalUrl || "";
        const method = req.method || "GET";

        // Single native crossing: classifies the URL for the graph detector and
        // evaluates the exclusion config registered above.
        const observation = observeRequest(exclusionConfigId, url);

        if (detectGraphReevaluation) {
          observe(observation.isModule, url);
        }

        if (excludedMethods && excludedMethods.has(method.toUpperCase())) {
          return next();
        }

        if (observation.excluded) {
          return next();
        }

        const serverFnDetails = isServerFnLoggingEnabled
          ? detectServerFunction(url, req.headers, serverFnConfig?.resolveServerFn, req)
          : null;

        // Shared capture plumbing (request listener + response write/end
        // patches, byte caps) — one copy for every adapter.
        const { bodyBytes, resBytes } = captureServerFnBodies(
          req,
          res,
          serverFnDetails !== null && serverFnConfig?.logArgs !== false && method !== "GET",
          serverFnDetails !== null && serverFnConfig?.logReturns !== false,
        );

        const start = performance.now();

        let logged = false;
        const logIt = (aborted: boolean) => {
          if (logged) return;
          logged = true;

          // Crucial memory leak optimization: remove listeners to release the closure
          res.removeListener("finish", onFinish);
          res.removeListener("close", onClose);

          const durationMs = performance.now() - start;
          // An aborted request never reaches `finish`, so statusCode is still the
          // default 200. Report 499 so a dropped request is not mistaken for a
          // successful one.
          const abortedRequest = aborted && !res.writableEnded;
          const status = abortedRequest ? 499 : res.statusCode;

          // Rolling latency footer: every completed non-excluded request feeds
          // the sample; the footer itself is emitted from a later microtask so
          // it renders below this request's own lines.
          if (summary) {
            summary.record(durationMs);
            if (!summaryFlushQueued) {
              summaryFlushQueued = true;
              queueMicrotask(() => {
                summaryFlushQueued = false;
                const sample = summary.poll();
                if (sample) {
                  sink.print(formatSummaryLine(sample, summaryWindowMs), {
                    kind: "summary",
                    ts: Date.now(),
                    windowMs: summaryWindowMs,
                    ...sample,
                  });
                }
              });
            }
          }

          const cl = res.getHeader("content-length");
          const contentLength = cl ? Number(cl) : null;
          const location = res.getHeader("location");
          const redirectLocation = location ? String(location) : null;
          const routeName = resolveRoute ? (resolveRoute(url) ?? null) : null;

          if (serverFnDetails) {
            const parsedArgs =
              serverFnConfig?.logArgs !== false ? parseServerFnArgs(url, method, req.headers, bodyBytes) : undefined;
            const parsedResult =
              serverFnConfig?.logReturns !== false ? parseServerFnResult(status, resBytes) : undefined;

            logServerFnCall({
              server,
              sink,
              details: serverFnDetails,
              url,
              method,
              status,
              durationMs,
              parsedArgs,
              parsedResult,
              outputFormat: serverFnFormat === "tree" ? "tree" : "standalone",
              limits: {
                maxDepth: serverFnConfig?.maxDepth,
                maxBreadth: serverFnConfig?.maxBreadth,
                maxStringLength: serverFnConfig?.maxStringLength,
              },
              browserConsole: serverFnConfig?.browserConsole === true,
            });
            return;
          }

          if (!groupRepeats) {
            const line = formatLogEntry(
              url,
              method,
              status,
              durationMs,
              contentLength,
              redirectLocation,
              routeName,
              null,
            );
            sink.print(
              line,
              buildRequestEvent(url, method, status, durationMs, {
                contentLength,
                location: redirectLocation,
                route: routeName,
              }),
            );
            return;
          }

          const key = `${method} ${url}`;
          const existing = repeats.get(key);
          if (existing) {
            existing.count += 1;
            existing.totalDurationMs += durationMs;
            existing.status = status;
            clearTimeout(existing.timer);
            existing.timer = setTimeout(() => flushRepeat(key, existing), repeatWindowMs);
            return;
          }

          const line = formatLogEntry(
            url,
            method,
            status,
            durationMs,
            contentLength,
            redirectLocation,
            routeName,
            null,
          );
          sink.print(
            line,
            buildRequestEvent(url, method, status, durationMs, {
              contentLength,
              location: redirectLocation,
              route: routeName,
            }),
          );

          const entry: PendingRepeat = {
            // Armed immediately so a trailing repeat lands in this entry, then
            // rewritten on every subsequent repeat to extend the window.
            timer: setTimeout(() => {}, 0),
            count: 1,
            totalDurationMs: durationMs,
            status,
            method,
            url,
          };
          entry.timer = setTimeout(() => flushRepeat(key, entry), repeatWindowMs);
          repeats.set(key, entry);
        };

        const onFinish = () => logIt(false);
        const onClose = () => logIt(true);

        // Listen for both finish and close to catch aborted requests
        res.on("finish", onFinish);
        res.on("close", onClose);

        next();
      });
    },
  };
}

/**
 * Builds the dev URL for the browser logger virtual module.
 *
 * Vite serves virtual modules under `/@id/` with the leading NUL encoded as
 * `__x00__`, and prefixes that with the resolved `base`. Hardcoding the URL breaks
 * any app served from a sub-path.
 *
 * @internal exported for tests
 */
export function browserLoggerScriptSrc(base: string): string {
  const normalized = base.endsWith("/") ? base : `${base}/`;
  return `${normalized}@id/__x00__virtual:browser-logger`;
}

export function browserLogger(config?: BrowserLoggerConfig): Plugin {
  const virtualModuleId = "virtual:browser-logger";
  const resolvedVirtualModuleId = "\0" + virtualModuleId;

  // Defaults to "/" so the tag is still correct if configResolved has not run yet.
  let base = "/";

  return {
    name: "vite-plugin-browser-logger",
    // Dev-only. Without this the transformIndexHtml injection below also runs
    // during `vite build` and ships a dev-only virtual module URL to production.
    apply: "serve",
    enforce: "pre",

    configResolved(cfg) {
      base = cfg.base;
    },

    // Expose a virtual module to run the browser logging script
    resolveId(id) {
      if (id === virtualModuleId || id === resolvedVirtualModuleId || id.endsWith(virtualModuleId)) {
        return resolvedVirtualModuleId;
      }
    },

    load(id) {
      if (id === resolvedVirtualModuleId || id.endsWith(virtualModuleId)) {
        const baseScript = getBrowserLoggerScript();
        const uiScript = config?.serverFunctionUi !== false ? getServerFunctionOverlayScript() : "";
        return baseScript + "\n" + uiScript;
      }
    },

    // Inject the virtual module into index.html so it runs unconditionally and early
    transformIndexHtml() {
      return [
        {
          tag: "script",
          attrs: { type: "module", src: browserLoggerScriptSrc(base) },
          injectTo: "head-prepend",
        },
      ];
    },

    configureServer(server) {
      interface PendingBrowserLog {
        timer: ReturnType<typeof setTimeout>;
        count: number;
        type: string;
        message: string;
        caller: string | null;
      }

      const sink = createLogSink({ json: config?.json === true, stripColors: config?.stripColors });
      const pendingBrowserLogs = new Map<string, PendingBrowserLog>();
      const MAX_PENDING_LOGS = 250;

      // Rolling print budget for flooded pages. A runaway `console.log` loop in
      // app code would otherwise pin the dev server CPU and make the terminal
      // unusable; past the budget only a one-line notice is printed per second.
      const PRINT_BUDGET_PER_SECOND = 400;
      let budgetStartAt = performance.now();
      let budgetUsed = 0;
      let budgetSuppressed = 0;

      const flushBrowserLog = (key: string) => {
        const entry = pendingBrowserLogs.get(key);
        if (!entry) return;
        pendingBrowserLogs.delete(key);

        const now = performance.now();
        const windowOver = now - budgetStartAt >= 1000;
        if (windowOver) {
          budgetStartAt = now;
          budgetUsed = 0;
          if (budgetSuppressed > 0) {
            const suppressed = budgetSuppressed;
            budgetSuppressed = 0;
            sink.print(`[hyperlog] ${suppressed} browser log rows suppressed (rate limit)`, {
              kind: "browser",
              ts: Date.now(),
              suppressed,
            });
          }
        }

        if (budgetUsed >= PRINT_BUDGET_PER_SECOND) {
          // Budget exhausted: count this batch toward the next-window notice and
          // drop the row.
          budgetSuppressed += entry.count;
          return;
        }
        budgetUsed += entry.count;

        const logString = formatBrowserLog(
          entry.type,
          entry.message,
          entry.caller,
          entry.count > 1 ? entry.count : null,
        );
        sink.print(logString, {
          kind: "browser",
          ts: Date.now(),
          type: entry.type,
          message: entry.message,
          caller: entry.caller,
          count: entry.count > 1 ? entry.count : null,
        });
      };

      server.httpServer?.on("close", () => {
        for (const [key, entry] of pendingBrowserLogs.entries()) {
          clearTimeout(entry.timer);
          flushBrowserLog(key);
        }
        sink.flush();
      });

      const handleBrowserLog = (data: { type: string; message: string; caller?: string | null }) => {
        const { type, message, caller } = data;
        const callerStr = caller ?? null;
        const key = `${type}:${message}:${callerStr ?? ""}`;

        const existing = pendingBrowserLogs.get(key);
        if (existing) {
          existing.count += 1;
          // Prevent starvation: if logs repeat rapidly, flush at batch of 20
          if (existing.count >= 20) {
            clearTimeout(existing.timer);
            flushBrowserLog(key);
            return;
          }
          clearTimeout(existing.timer);
          existing.timer = setTimeout(() => flushBrowserLog(key), 80);
          return;
        }

        // Prevent unbounded memory growth if unique logs flood
        if (pendingBrowserLogs.size >= MAX_PENDING_LOGS) {
          const firstKey = pendingBrowserLogs.keys().next().value;
          if (firstKey) flushBrowserLog(firstKey);
        }

        const entry: PendingBrowserLog = {
          count: 1,
          type,
          message,
          caller: callerStr,
          timer: setTimeout(() => flushBrowserLog(key), 80),
        };
        pendingBrowserLogs.set(key, entry);
      };

      server.ws.on("vite-plugin-hyperlog:browser-log", handleBrowserLog);

      attachRouteEndpoint(server, routeEventSinkHandler(sink));
    },
  };
}

/**
 * Convenient unified plugin that registers both requestLogger and browserLogger in one call.
 *
 * @example
 * ```ts
 * import logger from "vite-plugin-hyperlog";
 * export default defineConfig({
 *   plugins: [logger()],
 * });
 * ```
 */
export function logger(config?: RequestLoggerConfig): Plugin[] {
  const sf = config?.serverFunctions;
  // SAFETY: sf is validated to be a configuration object and not a boolean
  const sfConfig = Boolean(sf) && sf !== true ? (sf as ServerFunctionConfig) : undefined;
  const uiEnabled = config?.serverFunctions !== false && sfConfig?.ui !== false;
  return [
    requestLogger(config),
    browserLogger({ serverFunctionUi: uiEnabled, json: config?.json === true, stripColors: config?.stripColors }),
  ];
}

/**
 * Factory helper for framework-specific adapters (React, Solid, Svelte, Vue)
 * that injects default framework-specific exclusions while keeping behavior unified.
 */
export function createFrameworkLogger(defaultExclude: string) {
  function reqLogger(config?: RequestLoggerConfig): Plugin {
    return requestLogger({
      ...config,
      excludeUrls: [defaultExclude, ...(config?.excludeUrls || [])],
    });
  }
  function log(config?: RequestLoggerConfig): Plugin[] {
    const sf = config?.serverFunctions;
    // SAFETY: sf is validated to be a configuration object and not a boolean
    const sfConfig = Boolean(sf) && sf !== true ? (sf as ServerFunctionConfig) : undefined;
    const uiEnabled = config?.serverFunctions !== false && sfConfig?.ui !== false;
    return [
      reqLogger(config),
      browserLogger({ serverFunctionUi: uiEnabled, json: config?.json === true, stripColors: config?.stripColors }),
    ];
  }
  return { requestLogger: reqLogger, logger: log };
}

export default logger;
